import sys
sys.setrecursionlimit(1 << 25)

def main():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # 邻接表：g[u] = [(v, w), ...]
    g = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        g[u].append((v, w))
        g[v].append((u, w))

    # 计算加权直径
    def farthest(start):
        dist = [-1] * (n + 1)
        parent = [-1] * (n + 1)
        st = [start]
        dist[start] = 0
        while st:
            u = st.pop()
            for v, w in g[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                dist[v] = dist[u] + w
                st.append(v)
        idx = 1
        for i in range(1, n + 1):
            if dist[i] > dist[idx]:
                idx = i
        return idx, dist[idx]

    a, _ = farthest(1)
    _, dia = farthest(a)

    # 以分叉点1为根，建立父子关系与后序遍历
    parent = [0] * (n + 1)
    pw = [0] * (n + 1)           # 与父节点相连的枝条长度
    children = [[] for _ in range(n + 1)]
    post = []

    st = [(1, 0)]                # (节点, 状态) 0:进入 1:退出
    parent[1] = 0
    pw[1] = 0
    while st:
        u, t = st.pop()
        if t == 0:
            st.append((u, 1))
            for v, w in g[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                pw[v] = w
                children[u].append(v)
                st.append((v, 0))
        else:
            post.append(u)

    up = [0] * (n + 1)

    # 可行性检查
    def feasible(D):
        cuts = 0
        for u in reversed(post):
            A = []
            for v in children[u]:
                t = up[v] + pw[v]
                if t > D:
                    cuts += 1       # 枝条过长，必须切断
                else:
                    A.append(t)
            A.sort()
            # 保证经过 u 的两条最长路径之和不超过 D
            while len(A) >= 2 and A[-1] + A[-2] > D:
                A.pop()             # 删除较长的分支
                cuts += 1
            up[u] = A[-1] if A else 0
            if cuts > k:
                return False
        return cuts <= k

    lo, hi = 0, dia
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1

    print(lo)

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    static int n, k, idx;
    static int[] head, to, next, parent;
    static long[] w, pw, up;
    static ArrayList<Integer>[] children;
    static int[] post;
    static int postPtr;

    static void addEdge(int u, int v, long ww) {
        to[idx] = v;
        w[idx] = ww;
        next[idx] = head[u];
        head[u] = idx++;
    }

    // 计算从 start 出发能到达的最远节点
    static int farthestNode(int start) {
        long[] dist = new long[n + 1];
        Arrays.fill(dist, -1);
        int[] par = new int[n + 1];
        Arrays.fill(par, -1);
        int[] st = new int[n];
        int top = 0;
        st[top++] = start;
        dist[start] = 0;
        while (top > 0) {
            int u = st[--top];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v == par[u]) continue;
                par[v] = u;
                dist[v] = dist[u] + w[e];
                st[top++] = v;
            }
        }
        int best = 1;
        for (int i = 1; i <= n; i++) {
            if (dist[i] > dist[best]) best = i;
        }
        return best;
    }

    // 计算从 start 出发能到达的最远距离
    static long farthestDist(int start) {
        long[] dist = new long[n + 1];
        Arrays.fill(dist, -1);
        int[] par = new int[n + 1];
        Arrays.fill(par, -1);
        int[] st = new int[n];
        int top = 0;
        st[top++] = start;
        dist[start] = 0;
        while (top > 0) {
            int u = st[--top];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v == par[u]) continue;
                par[v] = u;
                dist[v] = dist[u] + w[e];
                st[top++] = v;
            }
        }
        long best = 0;
        for (int i = 1; i <= n; i++) best = Math.max(best, dist[i]);
        return best;
    }

    // 检查能否用不超过 k 次切断使所有连通块冠幅 <= D
    static boolean feasible(long D) {
        long cuts = 0;
        for (int p = postPtr - 1; p >= 0; p--) {
            int u = post[p];
            int sz = children[u].size();
            long[] arr = new long[sz];
            int tsz = 0;
            for (int v : children[u]) {
                long t = up[v] + pw[v];
                if (t > D) {
                    cuts++;
                } else {
                    arr[tsz++] = t;
                }
            }
            if (tsz > 1) {
                Arrays.sort(arr, 0, tsz);
                while (tsz >= 2 && arr[tsz - 1] + arr[tsz - 2] > D) {
                    tsz--;      // 删除最长的分支
                    cuts++;
                }
            }
            up[u] = (tsz > 0 ? arr[tsz - 1] : 0L);
            if (cuts > k) return false;
        }
        return cuts <= k;
    }

    public static void main(String[] args) throws Exception {
        // 快速输入
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        k = fs.nextInt();
        int m = 2 * (n - 1);
        head = new int[n + 1];
        to = new int[m];
        next = new int[m];
        w = new long[m];
        Arrays.fill(head, -1);
        idx = 0;

        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt(), v = fs.nextInt();
            long ww = fs.nextInt();
            addEdge(u, v, ww);
            addEdge(v, u, ww);
        }

        // 直径
        int a = farthestNode(1);
        long dia = farthestDist(a);

        // 以 1 为根建立父子关系与后序遍历
        parent = new int[n + 1];
        pw = new long[n + 1];
        children = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) children[i] = new ArrayList<>();
        post = new int[n];
        postPtr = 0;

        int[][] st = new int[2 * n][2];
        int top = 0;
        st[top][0] = 1;
        st[top][1] = 0;
        top++;
        parent[1] = 0;
        pw[1] = 0;
        while (top > 0) {
            int u = st[--top][0];
            int state = st[top][1];     // 刚弹出的状态
            if (state == 0) {
                st[top][0] = u; st[top][1] = 1; top++;
                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (v == parent[u]) continue;
                    parent[v] = u;
                    pw[v] = w[e];
                    children[u].add(v);
                    st[top][0] = v; st[top][1] = 0; top++;
                }
            } else {
                post[postPtr++] = u;
            }
        }

        up = new long[n + 1];

        long lo = 0, hi = dia;
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            if (feasible(mid)) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }

    // 快速输入类
    static class FastScanner {
        BufferedInputStream in;
        byte[] buffer = new byte[1 << 16];
        int ptr = 0, len = 0;

        FastScanner(InputStream is) { in = new BufferedInputStream(is); }

        int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++] & 0xff;
        }

        int nextInt() throws IOException {
            int c, s = 1, x = 0;
            do { c = read(); } while (c <= ' ');
            if (c == '-') { s = -1; c = read(); }
            while (c >= '0' && c <= '9') {
                x = x * 10 + (c - '0');
                c = read();
            }
            return x * s;
        }
    }
}
