```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct Edge { int to; ll w; };

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<vector<Edge>> g(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v; ll w;
        cin >> u >> v >> w;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    // 计算加权直径作为二分上界
    auto farthest = [&](int start) -> pair<int, ll> {
        vector<ll> dist(n + 1, -1);
        vector<int> parent(n + 1, -1);
        vector<int> st;
        st.reserve(n);
        st.push_back(start);
        dist[start] = 0;
        while (!st.empty()) {
            int u = st.back(); st.pop_back();
            for (auto &e : g[u]) {
                int v = e.to;
                if (v == parent[u]) continue;
                parent[v] = u;
                dist[v] = dist[u] + e.w;
                st.push_back(v);
            }
        }
        int idx = 1;
        for (int i = 1; i <= n; ++i) if (dist[i] > dist[idx]) idx = i;
        return {idx, dist[idx]};
    };
    int a = farthest(1).first;
    ll dia = farthest(a).second;

    // 以分叉点1为根，建立父子关系与后序遍历
    vector<int> parent(n + 1, 0);
    vector<ll> pw(n + 1, 0);       // 与父节点相连的枝条长度
    vector<vector<int>> children(n + 1);
    vector<int> post;
    post.reserve(n);

    {
        vector<pair<int, int>> st; // (节点, 状态) 0:进入 1:退出
        st.reserve(2 * n);
        parent[1] = 0; pw[1] = 0;
        st.push_back({1, 0});
        while (!st.empty()) {
            auto [u, t] = st.back(); st.pop_back();
            if (t == 0) {
                st.push_back({u, 1});
                for (auto &e : g[u]) {
                    int v = e.to;
                    if (v == parent[u]) continue;
                    parent[v] = u;
                    pw[v] = e.w;
                    children[u].push_back(v);
                    st.push_back({v, 0});
                }
            } else {
                post.push_back(u);
            }
        }
    }

    vector<ll> up(n + 1, 0);

    // 可行性检查：最多切断 k 条枝条，使所有连通块直径 <= D
    auto feasible = [&](ll D) -> bool {
        ll cuts = 0;
        for (int idx = (int)post.size() - 1; idx >= 0; --idx) {
            int u = post[idx];
            vector<ll> A;
            A.reserve(children[u].size());
            for (int v : children[u]) {
                ll t = up[v] + pw[v];
                if (t > D) {
                    ++cuts;          // 枝条过长，必须切断
                } else {
                    A.push_back(t);
                }
            }
            sort(A.begin(), A.end());
            // 最大两条路径长度之和不超过 D
            while ((int)A.size() >= 2 && A.back() + A[A.size() - 2] > D) {
                A.pop_back();        // 删除较长的分支
                ++cuts;
            }
            up[u] = A.empty() ? 0LL : A.back();
            if (cuts > k) return false;
        }
        return cuts <= k;
    };

    ll lo = 0, hi = dia;
    while (lo < hi) {
        ll mid = (lo + hi) >> 1;
        if (feasible(mid)) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << "\n";
    return 0;
}
